def table(headers,rows,widths=None,size=9):
 t=d.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
 if widths:
  for col,width in zip(t.columns,widths):col.width=Cm(width)
 for i,v in enumerate(headers):t.rows[0].cells[i].text=str(v)
 for row in rows:
  cells=t.add_row().cells
  for i,v in enumerate(row):cells[i].text=str(v)
 for ri,row in enumerate(t.rows):
  trpr=row._tr.get_or_add_trPr();e=OxmlElement('w:cantSplit');trpr.append(e)
  if ri==0:
   rep=OxmlElement('w:tblHeader');trpr.append(rep)
  for ci,cell in enumerate(row.cells):
   if widths:cell.width=Cm(widths[ci])
   cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
   tcpr=cell._tc.get_or_add_tcPr();sh=OxmlElement('w:shd');sh.set(qn('w:fill'),NAVY if ri==0 else PALE if ri%2==1 else 'FFFFFF');tcpr.append(sh)
   for par in cell.paragraphs:
    par.paragraph_format.space_after=Pt(3);par.paragraph_format.space_before=Pt(3)
    for run in par.runs:run.font.size=Pt(size);run.font.bold=ri==0;run.font.color.rgb=RGBColor.from_string('FFFFFF' if ri==0 else '1D2A38')
 return t
